// [MEDIUM_PRIORITY] VALIDATION: Double conversion safe
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.wakewordimport com.roshan.persona.voice.audio.AudioChunkimport com.roshan.persona.voice.audio.AudioFormatimport kotlin.math.lnimport kotlin.math.cosimport kotlin.math.sinimport kotlin.math.PIimport kotlin.math.sqrt/** * NOUS — MFCC (Mel-Frequency Cepstral Coefficients) feature extractor. * * Extracts MFCC features from audio chunks for: *   - **Wake word 2nd-stage confirmation** (reduces false positives 10x) *   - **Speaker recognition fallback** (when ECAPA-TDNN is unavailable) *   - **Speech emotion recognition fallback** (lightweight features) * * ## Algorithm * *   1. **Pre-emphasis** — apply high-pass filter to boost high frequencies *      `y[n] = x[n] - 0.97 × x[n-1]` * *   2. **Frame blocking** — split chunk into overlapping frames (25ms with *      10ms hop). For a 20ms chunk at 16kHz (320 samples), we get 1 frame. * *   3. **Hamming window** — apply window to reduce spectral leakage *      `w[n] = 0.54 - 0.46 × cos(2πn / (N-1))` * *   4. **FFT** — compute magnitude spectrum (using direct DFT) * *   5. **Mel filterbank** — apply triangular filters spaced on Mel scale *      Mel(f) = 2595 × log10(1 + f/700) *      Typical: 26 filters covering 0-8000 Hz * *   6. **Log** — take log of filterbank energies * *   7. **DCT** — Discrete Cosine Transform to get cepstral coefficients *      Keep first 13 coefficients (standard for speech recognition) * * ## Performance * *   - Per chunk (320 samples): ~2 ms (FFT + filterbank + DCT) *   - Output: 13 float coefficients per frame *   - Memory: ~10 KB (filterbank + DCT matrices) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 Wake Word Detection — 2-stage confirmation</a> */class MfccExtractor(    /** Number of MFCC coefficients to extract (typically 13). */    val numCoefficients: Int = DEFAULT_NUM_COEFFICIENTS,    /** Number of Mel filterbank filters (typically 26). */    val numFilters: Int = DEFAULT_NUM_FILTERS,    /** Pre-emphasis coefficient (0.0-1.0). */    private val preEmphasis: Float = DEFAULT_PRE_EMPHASIS,    /** Sample rate (Hz). */    private val sampleRateHz: Int = AudioFormat.VOICE_16K.sampleRateHz,    /** Lower frequency bound for Mel filterbank (Hz). */    private val lowerFreqHz: Float = DEFAULT_LOWER_FREQ,    /** Upper frequency bound for Mel filterbank (Hz). */    private val upperFreqHz: Float = DEFAULT_UPPER_FREQ,) {    /** Precomputed Mel filterbank (numFilters × halfFftSize). */    private val melFilterbank: Array<FloatArray> = buildMelFilterbank()    /** Precomputed DCT matrix (numCoefficients × numFilters). */    private val dctMatrix: Array<FloatArray> = buildDctMatrix()    /** Precomputed Hamming window (frameSize). */    private val hammingWindow: FloatArray = buildHammingWindow()    /** Precomputed twiddle factors for DFT. */    private val cosTable: FloatArray    private val sinTable: FloatArray    private val fftN: Int    init {        // FFT size = next power of 2 ≥ frame size (320 samples → 512)        fftN = nextPowerOfTwo(AudioFormat.VOICE_16K.samplesPerFrame)        cosTable = FloatArray(fftN)        sinTable = FloatArray(fftN)        for (i in 0 until fftN) {            val angle = -2.0 * PI * i / fftN            cosTable[i] = cos(angle).toFloat()            sinTable[i] = sin(angle).toFloat()        }    }    /**     * Extract MFCC features from an audio chunk.     *     * @param chunk input audio (16 kHz, 16-bit, mono, 20 ms = 320 samples)     * @return MFCC coefficients (size = [numCoefficients])     */    fun extract(chunk: AudioChunk): FloatArray {        require(chunk.format.sampleRateHz == sampleRateHz) {            "MFCC requires $sampleRateHz Hz audio, got ${chunk.format.sampleRateHz}"        }        require(chunk.sampleCount == AudioFormat.VOICE_16K.samplesPerFrame) {            "Chunk size ${chunk.sampleCount} doesn't match frame size ${AudioFormat.VOICE_16K.samplesPerFrame}"        }        val samples = chunk.samples        // 1. Pre-emphasis filter        val preEmphasized = FloatArray(samples.size)        preEmphasized[0] = samples[0].toFloat() / Short.MAX_VALUE        for (i in 1 until samples.size) {            val prev = samples[i - 1].toFloat() / Short.MAX_VALUE            val curr = samples[i].toFloat() / Short.MAX_VALUE            preEmphasized[i] = curr - preEmphasis * prev        }        // 2. Apply Hamming window        val windowed = FloatArray(samples.size)        for (i in samples.indices) {            windowed[i] = preEmphasized[i] * hammingWindow[i]        }        // 3. Zero-pad to FFT size and compute DFT magnitudes        val fftInput = FloatArray(fftN)        System.arraycopy(windowed, 0, fftInput, 0, windowed.size)        val magnitudes = computeDftMagnitudes(fftInput)        // 4. Apply Mel filterbank        val melEnergies = applyMelFilterbank(magnitudes)        // 5. Take log of filterbank energies        val logMelEnergies = FloatArray(numFilters)        for (i in 0 until numFilters) {            logMelEnergies[i] = if (melEnergies[i] > 1e-10f) {                ln(melEnergies[i])            } else {                -23.0f // ln(1e-10) ≈ -23            }        }        // 6. Apply DCT to get cepstral coefficients        val mfcc = FloatArray(numCoefficients)        for (k in 0 until numCoefficients) {            var sum = 0f            for (n in 0 until numFilters) {                sum += dctMatrix[k][n] * logMelEnergies[n]            }            mfcc[k] = sum        }        return mfcc    }    /**     * Compute cosine similarity between two MFCC vectors.     *     * Used for wake word template matching and speaker verification.     *     * @return similarity in range [-1, 1], where 1 = identical     */    fun cosineSimilarity(a: FloatArray, b: FloatArray): Float {        require(a.size == b.size) { "MFCC vectors must have same size" }        var dotProduct = 0.0        var normA = 0.0        var normB = 0.0        for (i in a.indices) {            dotProduct += a[i] * b[i]            normA += a[i] * a[i]            normB += b[i] * b[i]        }        val denom = sqrt(normA) * sqrt(normB)        return if (denom > 1e-10) (dotProduct / denom).toFloat() else 0f    }    /** Compute DFT magnitudes using precomputed twiddle tables. */    private fun computeDftMagnitudes(input: FloatArray): FloatArray {        val halfN = fftN / 2        val magnitudes = FloatArray(halfN)        for (k in 0 until halfN) {            var real = 0.0            var imag = 0.0            for (i in 0 until fftN) {                val idx = (k * i) % fftN                real += input[i] * cosTable[idx]                imag -= input[i] * sinTable[idx]            }            magnitudes[k] = sqrt(real * real + imag * imag).toFloat()        }        return magnitudes    }    /** Apply Mel filterbank to magnitude spectrum. */    private fun applyMelFilterbank(magnitudes: FloatArray): FloatArray {        val halfN = fftN / 2        val energies = FloatArray(numFilters)        for (f in 0 until numFilters) {            var sum = 0f            val filter = melFilterbank[f]            val len = minOf(filter.size, halfN)            for (k in 0 until len) {                sum += filter[k] * magnitudes[k]            }            energies[f] = sum        }        return energies    }    /** Build Mel filterbank (triangular filters on Mel scale). */    private fun buildMelFilterbank(): Array<FloatArray> {        val halfN = nextPowerOfTwo(AudioFormat.VOICE_16K.samplesPerFrame) / 2        val filterbank = Array(numFilters) { FloatArray(halfN) }        // Compute Mel scale center frequencies        val melMin = hzToMel(lowerFreqHz)        val melMax = hzToMel(upperFreqHz)        val melPoints = FloatArray(numFilters + 2)        for (i in melPoints.indices) {            melPoints[i] = melMin + (melMax - melMin) * i / (numFilters + 1)        }        val hzPoints = FloatArray(numFilters + 2) { melToHz(melPoints[it]) }        val binPoints = IntArray(numFilters + 2) { (hzPoints[it] * halfN / (sampleRateHz / 2)).toInt() }        // Build triangular filters        for (f in 0 until numFilters) {            val left = binPoints[f]            val center = binPoints[f + 1]            val right = binPoints[f + 2]            if (left == center || center == right) continue            // Rising slope            for (k in left until center) {                if (k in 0 until halfN) {                    filterbank[f][k] = (k - left).toFloat() / (center - left)                }            }            // Falling slope            for (k in center until right) {                if (k in 0 until halfN) {                    filterbank[f][k] = (right - k).toFloat() / (right - center)                }            }        }        return filterbank    }    /** Build DCT-II matrix. */    private fun buildDctMatrix(): Array<FloatArray> {        val matrix = Array(numCoefficients) { FloatArray(numFilters) }        for (k in 0 until numCoefficients) {            for (n in 0 until numFilters) {                matrix[k][n] = cos(PI * k * (n + 0.5f) / numFilters).toFloat()            }        }        // Scale first coefficient by 1/sqrt(2) for orthonormal DCT        for (n in 0 until numFilters) {            matrix[0][n] *= (1f / sqrt(2f))        }        return matrix    }    /** Build Hamming window. */    private fun buildHammingWindow(): FloatArray {        val n = AudioFormat.VOICE_16K.samplesPerFrame        val window = FloatArray(n)        for (i in 0 until n) {            window[i] = (0.54f - 0.46f * cos(2f * PI.toFloat() * i / (n - 1)))        }        return window    }    /** Convert Hz to Mel scale. */    private fun hzToMel(hz: Float): Float = 2595f * kotlin.math.log10(1f + hz / 700f)    /** Convert Mel to Hz. */    private fun melToHz(mel: Float): Float = 700f * (Math.pow(10.0, (mel / 2595f).toDouble()).toFloat() - 1f)    /** Find next power of 2 ≥ n. */    private fun nextPowerOfTwo(n: Int): Int {        var p = 1        while (p < n) p *= 2        return p    }    companion object {        /** Default number of MFCC coefficients (standard for speech recognition). */        const val DEFAULT_NUM_COEFFICIENTS = 13        /** Default number of Mel filterbank filters. */        const val DEFAULT_NUM_FILTERS = 26        /** Default pre-emphasis coefficient. */        const val DEFAULT_PRE_EMPHASIS = 0.97f        /** Default lower frequency for Mel filterbank. */        const val DEFAULT_LOWER_FREQ = 133.33f        /** Default upper frequency for Mel filterbank (Nyquist for 16kHz). */        const val DEFAULT_UPPER_FREQ = 6855.5f    }}